 pdfpath=ROOT/'reports/NuclearReaction-Lab-Scientific-Verification-v1.0.0.pdf';doc=SimpleDocTemplate(str(pdfpath),pagesize=A4,rightMargin=42,leftMargin=42,topMargin=63,bottomMargin=44,title='Nuclear Reaction Lab v1.0.0 - Scientific Verification',author='RagabLabs');story=[]
